#include <stdio.h>

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    int candidate = 0, count = 0;
    for (int i = 0; i < n; i++) {
        int val;
        scanf("%d", &val);
        if (count == 0) candidate = val;
        count += (val == candidate) ? 1 : -1;
    }
    printf("%d\n", candidate);
    return 0;
}
